using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
namespace HotelTogether {
 [RequireComponent(typeof(CharacterController))] public class HotelPlayer:MonoBehaviour {
  public Camera view;public float speed=2.7f,sprint=4.4f,sensitivity=.12f;public HotelItem held,cart,seated;public string message;public int bellCount;
  CharacterController cc;Rigidbody anchor;FixedJoint grip;float yaw=180,pitch,vertical;Quaternion holdOffset;HotelItem focused;float messageUntil;Vector3 spawn;Quaternion startRotation;readonly List<Rigidbody> cargo=new();Transform hands;Font font;float fps;
  void Start(){cc=GetComponent<CharacterController>();Physics.IgnoreLayerCollision(8,9,true);spawn=transform.position;startRotation=transform.rotation;yaw=transform.eulerAngles.y;var hand=new GameObject("Physics grip anchor");anchor=hand.AddComponent<Rigidbody>();anchor.isKinematic=true;anchor.useGravity=false;font=Font.CreateDynamicFontFromOSFont(new[]{"Thonburi","Tahoma","Arial"},18);CreateHands();}
  public void Notify(string text){message=text;messageUntil=Time.time+3;}
  public void CaptureMouse(){Cursor.lockState=CursorLockMode.Locked;Cursor.visible=false;}
  void Update(){fps=Mathf.Lerp(fps,1/Mathf.Max(Time.unscaledDeltaTime,.001f),.04f);var k=Keyboard.current;var m=Mouse.current;if(k==null||m==null)return;if(k.escapeKey.wasPressedThisFrame){Cursor.lockState=CursorLockMode.None;Cursor.visible=true;}if(Cursor.lockState!=CursorLockMode.Locked){if(m.leftButton.wasPressedThisFrame)CaptureMouse();return;}
   var delta=m.delta.ReadValue()*sensitivity;float newYaw=yaw+delta.x;if(cart)newYaw=Mathf.MoveTowardsAngle(yaw,newYaw,90*Time.deltaTime);pitch=Mathf.Clamp(pitch-delta.y,-75,75);
   float h=(k.dKey.isPressed?1:0)-(k.aKey.isPressed?1:0),v=(k.wKey.isPressed?1:0)-(k.sKey.isPressed?1:0);Vector3 move=Quaternion.Euler(0,newYaw,0)*new Vector3(h,0,v).normalized*(k.leftShiftKey.isPressed?sprint:speed)*Time.deltaTime;
   if(cart&&!ClearCart(transform.position+move,newYaw)){move=Vector3.zero;newYaw=yaw;Notify("มีสิ่งของขวางรถเข็น");}yaw=newYaw;transform.rotation=Quaternion.Euler(0,yaw,0);view.transform.localRotation=Quaternion.Euler(pitch,0,0);
   if(!seated){if(cc.isGrounded&&vertical<0)vertical=-2;vertical+=Physics.gravity.y*Time.deltaTime;cc.Move(move+Vector3.up*vertical*Time.deltaTime);}
   focused=null;if(Physics.Raycast(view.transform.position,view.transform.forward,out var hit,3.1f,~((1<<8)|(1<<9)),QueryTriggerInteraction.Collide)){focused=hit.collider.GetComponentInParent<HotelItem>();if(!focused)focused=hit.collider.GetComponentInParent<DoorLeaf>()?.owner;}
   if(k.eKey.wasPressedThisFrame)Use();if(k.qKey.wasPressedThisFrame)Drop();if(k.spaceKey.wasPressedThisFrame&&held)Drop(true);if(k.rKey.wasPressedThisFrame)ResetWorld();
   hands.gameObject.SetActive(cart!=null);if(cart)UpdateHands();
  }
  void FixedUpdate(){if(held){Vector3 target=view.transform.position+view.transform.forward*1.4f;if(Physics.Raycast(view.transform.position,view.transform.forward,out var hit,1.65f,~((1<<8)|(1<<9)),QueryTriggerInteraction.Ignore))target=view.transform.position+view.transform.forward*Mathf.Max(.45f,hit.distance-held.dimensions.magnitude*.25f-.06f);anchor.MovePosition(Vector3.MoveTowards(anchor.position,target,Time.fixedDeltaTime*5));anchor.MoveRotation(Quaternion.Euler(0,yaw,0)*holdOffset);}if(cart){var rb=cart.GetComponent<Rigidbody>();rb.MovePosition(CartPosition(transform.position,yaw));rb.MoveRotation(Quaternion.Euler(0,yaw-90,0));}}
  void Use(){if(seated){Stand();return;}if(cart){EndCart();return;}if(focused&&focused.kind=="door"){focused.open=!focused.open;Notify((focused.open?"เปิด":"ปิด")+focused.displayName);return;}if(held){Drop();return;}if(!focused)return;switch(focused.kind){case "pickup":case "mop":PickUp(focused);break;case "cart":BeginCart(focused);break;case "seat":Sit(focused);break;case "lamp":focused.lampOn=!focused.lampOn;if(focused.lamp)focused.lamp.enabled=focused.lampOn;Notify((focused.lampOn?"เปิด":"ปิด")+focused.displayName);break;case "bell":Bell();break;default:Notify("ระบบใช้งานส่วนนี้จะย้ายในขั้นต่อไป");break;}}
  void PickUp(HotelItem o){held=o;var rb=o.GetComponent<Rigidbody>();if(!rb)rb=o.gameObject.AddComponent<Rigidbody>();rb.isKinematic=false;rb.mass=Mathf.Max(.15f,rb.mass);rb.interpolation=RigidbodyInterpolation.Interpolate;rb.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;rb.linearVelocity=Vector3.zero;anchor.position=rb.position;anchor.rotation=rb.rotation;holdOffset=Quaternion.Inverse(Quaternion.Euler(0,yaw,0))*rb.rotation;SetLayer(o.transform,9);grip=o.gameObject.AddComponent<FixedJoint>();grip.connectedBody=anchor;grip.enableCollision=false;grip.breakForce=float.PositiveInfinity;Notify("Q วาง · Space โยน");}
  public void Drop(bool throwIt=false){if(!held)return;var rb=held.GetComponent<Rigidbody>();if(grip)Destroy(grip);grip=null;SetLayer(held.transform,0);rb.isKinematic=false;if(throwIt)rb.linearVelocity=view.transform.forward*6+Vector3.up;held=null;}
  static void SetLayer(Transform t,int layer){t.gameObject.layer=layer;foreach(Transform c in t)SetLayer(c,layer);}
  Vector3 CartPosition(Vector3 player,float heading)=>player+Quaternion.Euler(0,heading,0)*Vector3.forward*1.12f+Vector3.up*(cart.home.y-player.y);
  bool ClearCart(Vector3 pos,float heading){if(!cart)return true;var desired=CartPosition(pos,heading);var rot=Quaternion.Euler(0,heading-90,0);int steps=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(cart.transform.position,desired)/.1f),Mathf.CeilToInt(Quaternion.Angle(cart.transform.rotation,rot)/8));var colliders=cart.GetComponentsInChildren<BoxCollider>();for(int i=1;i<=steps;i++){var p=Vector3.Lerp(cart.transform.position,desired,(float)i/steps);var q=Quaternion.Slerp(cart.transform.rotation,rot,(float)i/steps);foreach(var box in colliders){if(box.transform.GetComponentInParent<HotelItem>()!=cart)continue;var local=cart.transform.InverseTransformPoint(box.transform.TransformPoint(box.center));var half=Vector3.Scale(box.size,box.transform.lossyScale)*.5f-Vector3.one*.018f;half=Vector3.Max(half,Vector3.one*.005f);var relative=Quaternion.Inverse(cart.transform.rotation)*box.transform.rotation;foreach(var c in Physics.OverlapBox(p+q*local,half,q*relative,~(1<<8),QueryTriggerInteraction.Ignore)){if(c.transform.IsChildOf(cart.transform)||c.transform.IsChildOf(transform))continue;return false;}}}return true;}
  void BeginCart(HotelItem o){cart=o;var rb=o.GetComponent<Rigidbody>();if(!rb)rb=o.gameObject.AddComponent<Rigidbody>();foreach(var a in FindObjectsByType<HotelItem>(FindObjectsSortMode.None)){var r=a.GetComponent<Rigidbody>();if(!r||r==rb||r.isKinematic)continue;float bottom=a.transform.position.y-a.dimensions.y/2;float baseY=o.transform.position.y-o.dimensions.y/2;if(Vector2.Distance(new Vector2(a.transform.position.x,a.transform.position.z),new Vector2(o.transform.position.x,o.transform.position.z))<.5f&&bottom>baseY+.27f&&bottom<baseY+.5f){r.isKinematic=true;a.transform.SetParent(o.transform,true);cargo.Add(r);}}
   if(!ClearCart(transform.position,yaw)){EndCart();Notify("พื้นที่ด้านหน้าไม่พอ · ขยับแล้วลองใหม่");return;}rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;rb.isKinematic=true;rb.position=CartPosition(transform.position,yaw);rb.rotation=Quaternion.Euler(0,yaw-90,0);hands.gameObject.SetActive(true);UpdateHands();Notify("จับราวรถเข็นแล้ว · E ปล่อย");}
  public void EndCart(){if(!cart)return;var rb=cart.GetComponent<Rigidbody>();rb.isKinematic=false;rb.linearVelocity=Vector3.zero;foreach(var r in cargo){r.transform.SetParent(cart.transform.parent,true);r.isKinematic=false;}cargo.Clear();cart=null;hands.gameObject.SetActive(false);}
  void Sit(HotelItem o){seated=o;cc.enabled=false;transform.position=new Vector3(o.transform.position.x,o.home.y-o.dimensions.y/2+.025f,o.transform.position.z);view.transform.localPosition=Vector3.up*o.seatEyeHeight;Notify("E ลุกจากเก้าอี้");}
  void Stand(){var s=seated;if(!s)return;Vector3 target=s.transform.position+s.transform.forward*(s.dimensions.z/2+.75f);target.y=spawn.y;if(Physics.CheckCapsule(target+Vector3.up*.35f,target+Vector3.up*1.35f,.28f,~((1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)){target=s.transform.position-s.transform.forward*(s.dimensions.z/2+.75f);target.y=spawn.y;}transform.position=target;view.transform.localPosition=Vector3.up*1.62f;cc.enabled=true;vertical=0;seated=null;}
  public void ResetWorld(){Drop();EndCart();seated=null;cc.enabled=false;transform.SetPositionAndRotation(spawn,startRotation);view.transform.localPosition=Vector3.up*1.62f;pitch=0;yaw=startRotation.eulerAngles.y;cc.enabled=true;foreach(var o in FindObjectsByType<HotelItem>(FindObjectsSortMode.None))o.ResetItem();Physics.SyncTransforms();Notify("เริ่มใหม่แล้ว");}
  void Bell(){bellCount++;var clip=AudioClip.Create("Reception bell",24000,1,24000,false);var samples=new float[24000];for(int i=0;i<samples.Length;i++){float t=i/24000f;samples[i]=Mathf.Sin(2*Mathf.PI*1568*t)*.15f*Mathf.Exp(-t*7);}clip.SetData(samples,0);AudioSource.PlayClipAtPoint(clip,focused.transform.position,.7f);Destroy(clip,2);Notify("กริ๊ง · เรียกพนักงานเช็กอิน");}
  void CreateHands(){hands=new GameObject("Cart grip hands").transform;var skin=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=new Color(.85f,.66f,.47f)};var sleeve=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=new Color(.13f,.28f,.34f)};for(int i=0;i<2;i++){var group=new GameObject("Hand "+i).transform;group.SetParent(hands);for(int j=0;j<3;j++){var n=GameObject.CreatePrimitive(j==0?PrimitiveType.Sphere:PrimitiveType.Cylinder);n.transform.SetParent(group);n.GetComponent<Renderer>().sharedMaterial=j==1?sleeve:skin;Destroy(n.GetComponent<Collider>());n.layer=8;} }hands.gameObject.SetActive(false);}
  void Segment(Transform t,Vector3 a,Vector3 b,float radius){t.position=(a+b)*.5f;t.rotation=Quaternion.FromToRotation(Vector3.up,b-a);t.localScale=new Vector3(radius,(b-a).magnitude/2,radius);}
  void UpdateHands(){for(int i=0;i<2;i++){float side=i==0?-1:1;var hand=hands.GetChild(i);Vector3 wrist=cart.transform.TransformPoint(new Vector3(-.46f,-cart.dimensions.y/2+1.08f,side*.16f));Vector3 shoulder=transform.position+transform.right*side*.24f+Vector3.up*1.25f,elbow=(shoulder+wrist)*.5f-Vector3.up*.14f;hand.GetChild(0).position=wrist;hand.GetChild(0).rotation=cart.transform.rotation;hand.GetChild(0).localScale=new Vector3(.12f,.085f,.12f);Segment(hand.GetChild(1),shoulder,elbow,.10f);Segment(hand.GetChild(2),elbow,wrist,.07f);}}
  void OnGUI(){GUI.skin.font=font;GUI.color=Color.white;GUI.Box(new Rect(16,16,330,80),"HOTEL TOGETHER\nWASD เดิน · Shift วิ่ง · E ใช้งาน\nQ วาง · Space โยน · R เริ่มใหม่ · Esc เมนู");GUI.Label(new Rect(Screen.width/2-6,Screen.height/2-12,24,24),"+");string text=seated?"E · ลุก":cart?"E · ปล่อยรถเข็น":held?"Q วาง · Space โยน":focused?"E · "+focused.displayName:"";if(text!="")GUI.Box(new Rect(Screen.width/2-180,Screen.height-110,360,32),text);if(Time.time<messageUntil)GUI.Box(new Rect(Screen.width/2-200,Screen.height-155,400,32),message);if(Cursor.lockState!=CursorLockMode.Locked){GUI.Box(new Rect(Screen.width/2-170,Screen.height/2-85,340,170),"HotelTogether");if(GUI.Button(new Rect(Screen.width/2-110,Screen.height/2-35,220,45),"เข้าเล่น / เล่นต่อ"))CaptureMouse();if(GUI.Button(new Rect(Screen.width/2-110,Screen.height/2+20,220,35),"เริ่มใหม่")){ResetWorld();CaptureMouse();}}}
 }
}
